export const PLUGIN_FILES: Record<string, string> = {
  "plugin/bash/adapter.bash": "# bash adapter: hooks, readline access, history.\n#\n# bash has no pre-execution hook, so this adapter deliberately does *not*\n# intercept Enter:\n#   * natural language is simply executed and lands in the\n#     command-not-found path (the shell prints one \"command not found\" line);\n#   * bind -x on Enter would consume that keystroke, and bash cannot pass it\n#     through in the same keypress without eval (which breaks interactive\n#     programs) — measured.\n# Delivery of a suggestion therefore uses a one-shot Enter handler, armed only\n# while a suggestion is pending: the Enter that would have been a no-op on an\n# empty line accepts the suggestion instead.\n\n_unstuck_adapter_init() {\n  command_not_found_handle() { UNSTUCK_LAST_CMD=\"$*\"; _unstuck_on_not_found \"$1\"; }\n\n  # Ours must run first: every other PROMPT_COMMAND entry would clobber $?.\n  local entry=_unstuck_bash_prompt\n  if [[ $(declare -p PROMPT_COMMAND 2>/dev/null) == \"declare -a\"* ]]; then\n    local -a rebuilt=(\"$entry\")\n    local existing\n    for existing in \"${PROMPT_COMMAND[@]}\"; do\n      [[ $existing == \"$entry\" ]] || rebuilt+=(\"$existing\")\n    done\n    PROMPT_COMMAND=(\"${rebuilt[@]}\")\n  else\n    case \";${PROMPT_COMMAND-};\" in\n      *\";$entry;\"*) : ;;\n      *) PROMPT_COMMAND=\"$entry${PROMPT_COMMAND:+;$PROMPT_COMMAND}\" ;;\n    esac\n  fi\n\n  trap _unstuck_bash_exit EXIT\n}\n\n_unstuck_adapter_finish() { return 0; }\n\n# bash's `history` prints \"  <n>  <command>\"; strip the number (and any\n# HISTTIMEFORMAT prefix) without forking.\n_unstuck_bash_strip_number() {\n  local text=$1\n  text=${text#\"${text%%[![:space:]]*}\"}      # leading blanks\n  [[ $text == \\[*\\]* ]] && text=${text#*]}   # HISTTIMEFORMAT prefix, if any\n  text=${text#\"${text%%[![:space:]]*}\"}\n  text=${text#\"${text%%[!0-9]*}\"}            # the entry number\n  text=${text#\"${text%%[![:space:]]*}\"}      # blanks after it\n  printf '%s' \"$text\"\n}\n\n_unstuck_adapter_history() {\n  local limit=${1:-20} line\n  local -a lines=()\n  while IFS= read -r line; do\n    line=$(_unstuck_bash_strip_number \"$line\")\n    [[ -n $line ]] && lines+=(\"$line\")\n  done < <(history \"$limit\" 2>/dev/null)\n  (( ${#lines[@]} )) && printf '%s\\n' \"${lines[@]}\"\n  return 0\n}\n\n_unstuck_bash_last_command() {\n  local line\n  line=$(history 1 2>/dev/null) || return 0\n  _unstuck_bash_strip_number \"$line\"\n}\n\n_unstuck_adapter_not_found_message() { printf 'bash: %s: command not found\\n' \"$1\" >&2; }\n\n_unstuck_adapter_command_exists() { command -v -- \"$1\" >/dev/null 2>&1; }\n\n# bash enables this by default, so suggestions can carry their rationale inline.\n_unstuck_adapter_supports_comment() { shopt -q interactive_comments; }\n\n_unstuck_adapter_delivery() { printf 'enter'; }\n\n# Arm the one-shot Enter handler.  `bind` only affects the current shell, so this\n# must run in the prompt hook (never inside the command-not-found subshell).  The\n# \"press Enter\" instruction is printed by the runtime inside the panel.\n_unstuck_adapter_pending_ready() {\n  [[ $- == *i* ]] || return 0\n  bind -x '\"\\C-m\": _unstuck_bash_accept' 2>/dev/null || return 0\n}\n\n_unstuck_bash_accept() {\n  # The user started typing instead of accepting — never clobber their line.\n  if [[ -n ${READLINE_LINE-} ]]; then\n    bind '\"\\C-m\": accept-line'\n    return 0\n  fi\n  local suggestion\n  suggestion=$(cat \"$UNSTUCK_PENDING\" 2>/dev/null)\n  READLINE_LINE=$suggestion\n  READLINE_POINT=${#suggestion}\n  rm -f -- \"$UNSTUCK_PENDING\"\n  bind '\"\\C-m\": accept-line'\n}\n\n_unstuck_bash_prompt() {\n  local ret=$? marker=${HISTCMD:-0}\n  # An empty line keeps $? (measured), so without this guard a bare Enter after a\n  # failure would re-analyse the same command on every keystroke-less prompt.\n  if [[ $marker == \"${UNSTUCK_LAST_HISTCMD:-}\" ]]; then\n    _unstuck_on_prompt 0 \"\"\n    return $ret\n  fi\n  UNSTUCK_LAST_HISTCMD=$marker\n  _unstuck_on_prompt \"$ret\" \"$(_unstuck_bash_last_command)\"\n  return $ret\n}\n\n_unstuck_adapter_doctor() {\n  if declare -F command_not_found_handle >/dev/null 2>&1; then\n    printf 'not-found   : unstuck 已接管\\n'\n  else\n    printf 'not-found   : 未接管\\n'\n  fi\n  case \"${PROMPT_COMMAND-}\" in\n    *_unstuck_bash_prompt*) printf 'prompt hook : 已挂载\\n' ;;\n    *) printf 'prompt hook : 未挂载\\n' ;;\n  esac\n  printf 'comments    : %s\\n' \"$(shopt -q interactive_comments && printf on || printf off)\"\n}\n\n_unstuck_bash_exit() {\n  # Subshells inherit the EXIT trap; only the main shell may clean up.\n  [[ ${BASHPID:-$$} == $$ ]] || return 0\n  rm -rf -- \"$UNSTUCK_SESSION_DIR\"\n}\n",
  "plugin/bash/unstuck.bash": "# Unstuck — bash integration entry point (bash 5+; macOS needs `brew install bash`).\n#\n# The policy, context assembly and runtime bridge live in\n# plugin/lib/unstuck-core.sh; this directory only implements what is\n# bash-specific (see plugin/bash/adapter.bash).\n\n[[ -n ${UNSTUCK_LOADED-} ]] && return 0\nUNSTUCK_LOADED=1\nUNSTUCK_NAME=bash\nUNSTUCK_EXT=bash\n\n# <repo>/plugin/bash/unstuck.bash -> <repo>\nUNSTUCK_ROOT=$(cd -- \"$(dirname -- \"${BASH_SOURCE[0]}\")/../..\" && pwd)\n\n. \"$UNSTUCK_ROOT/plugin/lib/unstuck-core.sh\"\n. \"$UNSTUCK_ROOT/plugin/bash/adapter.bash\"\n\n_unstuck_setup\n",
  "plugin/lib/unstuck-core.sh": "# unstuck core — shell-agnostic policy, context assembly and the runtime bridge.\n#\n# Sourced by plugin/<shell>/unstuck.*.  Nothing in here may use shell-specific\n# syntax: it runs under both zsh and bash.  Everything that *is*\n# shell-specific — hooks, line-editor access, history, option names — lives in\n# the per-shell adapter, which must provide:\n#\n#   _unstuck_adapter_init                  register the shell's hooks\n#   _unstuck_adapter_finish                unregister the shell's hooks\n#   _unstuck_adapter_history <n>           print up to n recent commands\n#   _unstuck_adapter_command_exists <word> 0 = the shell can resolve it\n#   _unstuck_adapter_supports_comment      0 = '#' starts a comment here\n#   _unstuck_adapter_pending_ready <cmd>   the shell may deliver a suggestion\n#   _unstuck_adapter_delivery             \"prefill\" or \"enter\" (how it is delivered)\n#   _unstuck_adapter_doctor                print shell-side facts\n#\n# Contract with the runtime (unchanged across shells): 11 NUL-separated fields\n# on stdin, human-readable panel on stdout, suggestion via --command-out.\n\n_unstuck_setup() {\n  : \"${UNSTUCK_ROOT:?unstuck core needs UNSTUCK_ROOT}\"\n  : \"${UNSTUCK_NAME:?unstuck core needs UNSTUCK_NAME}\"\n\n  # `$$` is the *main* shell's pid in both shells, so subshells (the\n  # command-not-found handler runs in one) share the parent's session.\n  UNSTUCK_SESSION_DIR=\"${TMPDIR:-/tmp}/unstuck-${UID:-$(id -u)}-$$\"\n  export UNSTUCK_SESSION_DIR\n  [[ -d $UNSTUCK_SESSION_DIR ]] || mkdir -p -- \"$UNSTUCK_SESSION_DIR\"\n  UNSTUCK_PENDING=$UNSTUCK_SESSION_DIR/pending\n  UNSTUCK_CNF_TRIGGER=$UNSTUCK_SESSION_DIR/cnf-trigger\n  UNSTUCK_CNF_QUERY=$UNSTUCK_SESSION_DIR/cnf-query\n\n  UNSTUCK_LOG_FILE=${UNSTUCK_LOG_FILE:-$UNSTUCK_SESSION_DIR/log}\n  UNSTUCK_MAX_EXIT_AI=${UNSTUCK_MAX_EXIT_AI:-3}\n  UNSTUCK_FAIL_STREAK=${UNSTUCK_FAIL_STREAK:-0}\n  UNSTUCK_LAST_CMD=\"\"\n  UNSTUCK_QUERY=\"\"\n  # Commands whose non-zero exit is normal, not a failure to explain.\n  UNSTUCK_IGNORE=${UNSTUCK_IGNORE:-\"grep egrep fgrep rg ag ack diff cmp test [ [[ false\"}\n\n  _unstuck_resolve_runtime\n  _unstuck_adapter_init\n}\n\n# How the runtime is invoked: an explicit binary (UNSTUCK_BIN), one installed on\n# PATH, or — for in-repo development — node running the TypeScript directly.\n_unstuck_resolve_runtime() {\n  if [[ -n ${UNSTUCK_BIN:-} ]]; then\n    UNSTUCK_CMD=(\"$UNSTUCK_BIN\")\n  elif command -v unstuck >/dev/null 2>&1; then\n    UNSTUCK_CMD=(\"$(command -v unstuck)\")\n  else\n    UNSTUCK_CMD=(node \"$UNSTUCK_ROOT/runtime/main.ts\")\n  fi\n}\n\n_unstuck_reload() {\n  unset UNSTUCK_LOADED\n  _unstuck_adapter_finish\n  . \"$UNSTUCK_ROOT/plugin/$UNSTUCK_NAME/unstuck.$UNSTUCK_EXT\"\n}\n\n# --- small utilities used by every shell ------------------------------------\n\n_unstuck_first_word() {\n  local s=$1\n  s=${s#\"${s%%[![:space:]]*}\"}\n  printf '%s' \"${s%%[[:space:]]*}\"\n}\n\n# $1 = command name; uses the shell's own resolution via the adapter.\n_unstuck_ignored() {\n  case \" $UNSTUCK_IGNORE $UNSTUCK_IGNORE_EXTRA \" in\n    *\" $1 \"*) return 0 ;;\n  esac\n  return 1\n}\n\n# Monotonic-ish milliseconds; EPOCHREALTIME exists in zsh (zsh/datetime) and\n# bash >= 5.  `10#` keeps the fractional digits from being read as octal.\n_unstuck_now_ms() {\n  local t=${EPOCHREALTIME:-} frac\n  if [[ -n $t ]]; then\n    # Fraction precision differs per shell (bash: µs, zsh: ns) — take 3 digits.\n    frac=\"${t#*.}000\"\n    printf '%s' \"$(( ${t%.*} * 1000 + 10#${frac:0:3} ))\"\n  else\n    printf '%s' \"$(( ${EPOCHSECONDS:-0} * 1000 ))\"\n  fi\n}\n\n_unstuck_log() {\n  # $1 trigger $2 ms $3 rc $4 command\n  [[ -n ${UNSTUCK_LOG:-} ]] || return 0\n  printf '%s\\n' \"trigger=$1 ms=$2 rc=$3 cmd=$4\" >> \"$UNSTUCK_LOG_FILE\"\n}\n\n# --- context + runtime -------------------------------------------------------\n\n# Field order is fixed by runtime/context.ts.  The trailing \"  # rationale\" the\n# runtime appends to suggestions is stripped: fed back as context it made the\n# model explain its own comment instead of the failure.\n_unstuck_context() {\n  # $1=trigger $2=buffer $3=last command $4=exit code\n  printf '%s\\0' \"1\"\n  printf '%s\\0' \"$UNSTUCK_NAME\"\n  printf '%s\\0' \"$PWD\"\n  printf '%s\\0' \"${2%%  \\# *}\"\n  printf '%s\\0' \"${3%%  \\# *}\"\n  printf '%s\\0' \"$4\"\n  printf '%s\\0' \"$1\"\n  printf '%s\\0' \"$(_unstuck_adapter_history 20)\"\n  printf '%s\\0' \"$(env)\"\n  printf '%s\\0' \"$UNSTUCK_PENDING\"\n  printf '%s\\0' \"$(uname -srm 2>/dev/null)\"\n}\n\n# Runs the runtime: it streams the panel to the terminal and writes the\n# suggestion to the pending file.  Always returns 0 — a broken AI call must\n# never change the shell's behaviour.\n_unstuck_ask() {\n  # $1=trigger $2=buffer $3=last command $4=exit code\n  local trigger=$1 start_ms\n  start_ms=$(_unstuck_now_ms)\n  rm -f -- \"$UNSTUCK_PENDING\"\n\n  local extra=()\n  [[ -n ${UNSTUCK_MODEL:-} ]] && extra+=(--model \"$UNSTUCK_MODEL\")\n  [[ -n ${UNSTUCK_TIMEOUT_MS:-} ]] && extra+=(--timeout \"$UNSTUCK_TIMEOUT_MS\")\n  if _unstuck_adapter_supports_comment; then extra+=(--comment); fi\n  extra+=(--delivery \"$(_unstuck_adapter_delivery)\")\n\n  _unstuck_context \"$@\" | \"${UNSTUCK_CMD[@]}\" ask --command-out \"$UNSTUCK_PENDING\" \"${extra[@]}\"\n  local rc=$?\n\n  _unstuck_log \"$trigger\" \"$(( $(_unstuck_now_ms) - start_ms ))\" \"$rc\" \"$3\"\n  return 0\n}\n\n# --- trigger policies --------------------------------------------------------\n\n# Non-ASCII and nothing the shell can resolve ⇒ the user typed a question, not a\n# command.  Shared by the pre-execution hook (zsh) and the command-not-found\n# handler (bash) so both shells frame the input the same way.\n_unstuck_looks_like_natural_language() {\n  local line=$1 first saved_lc=${LC_ALL-}\n  case ${line:0:1} in\n    '' | '#' | '|' | '&' | ';' | '(' | ')' | '<' | '>') return 1 ;;\n  esac\n  # LC_ALL=C makes [:print:] byte-based, so non-ASCII is detected regardless of\n  # the user's locale.\n  LC_ALL=C\n  case $line in\n    *[![:print:][:space:]]*) : ;;\n    *) LC_ALL=$saved_lc; return 1 ;;\n  esac\n  LC_ALL=$saved_lc\n  first=$(_unstuck_first_word \"$line\")\n  [[ -n $first ]] || return 1\n  case $first in\n    */*) return 1 ;;   # a path: let the shell report it, it is not a question\n  esac\n  _unstuck_adapter_command_exists \"$first\" && return 1\n  return 0\n}\n\n# Natural language typed at the prompt (shells with a pre-execution hook).\n# Deliberately conservative: everything that is not clearly a question goes to\n# the shell untouched.\n_unstuck_should_intercept_line() {\n  [[ -n ${UNSTUCK_DISABLE:-} ]] && return 1\n  _unstuck_looks_like_natural_language \"$1\"\n}\n\n# Called by the shell's command-not-found hook (runs in a subshell in both zsh\n# and bash, so only file-based side effects survive).\n_unstuck_on_not_found() {\n  local cmd=$1 line=${UNSTUCK_LAST_CMD:-$1}\n\n  if [[ -n ${UNSTUCK_DISABLE:-} ]]; then\n    _unstuck_adapter_not_found_message \"$cmd\"\n    return 127\n  fi\n\n  if _unstuck_looks_like_natural_language \"$line\"; then\n    # A question, not a mistyped command: skip the shell's own error line and\n    # defer it to the prompt hook, so the parent shell owns delivery.\n    printf '%s' \"nl\" > \"$UNSTUCK_CNF_TRIGGER\"\n    printf '%s' \"$line\" > \"$UNSTUCK_CNF_QUERY\"\n    return 127\n  fi\n\n  _unstuck_adapter_not_found_message \"$cmd\"\n  # iZSH writes command_end only after this handler returns. Deferring the AI\n  # call to precmd makes the completed stdout/stderr available to the runtime.\n  printf '%s' \"command_not_found\" > \"$UNSTUCK_CNF_TRIGGER\"\n  printf '%s' \"$line\" > \"$UNSTUCK_CNF_QUERY\"\n  return 127\n}\n\n# Called once per prompt, with the exit status of the command that just ran.\n_unstuck_on_prompt() {\n  local ret=$1 last=${2:-}\n\n  if [[ -n ${UNSTUCK_QUERY:-} ]]; then\n    # A natural-language line intercepted before execution (see the adapter).\n    local query=$UNSTUCK_QUERY\n    UNSTUCK_QUERY=\"\"\n    _unstuck_ask nl \"$query\" \"\" \"\"\n    _unstuck_queue_pending\n    return $ret\n  fi\n\n  if [[ -s $UNSTUCK_CNF_TRIGGER ]]; then\n    local trigger query\n    trigger=$(cat \"$UNSTUCK_CNF_TRIGGER\" 2>/dev/null)\n    query=$(cat \"$UNSTUCK_CNF_QUERY\" 2>/dev/null)\n    rm -f -- \"$UNSTUCK_CNF_TRIGGER\" \"$UNSTUCK_CNF_QUERY\"\n    case $trigger in\n      nl) _unstuck_ask nl \"$query\" \"\" 127 ;;\n      command_not_found) _unstuck_ask command_not_found \"$query\" \"$query\" 127 ;;\n    esac\n    _unstuck_queue_pending\n    return $ret\n  fi\n\n  if [[ -z ${UNSTUCK_DISABLE:-} ]]; then\n    if (( ret == 0 || ret == 130 )); then\n      UNSTUCK_FAIL_STREAK=0\n    else\n      local first\n      first=$(_unstuck_first_word \"$last\")\n      if [[ -n $first ]] && ! _unstuck_ignored \"$first\"; then\n        UNSTUCK_FAIL_STREAK=$(( UNSTUCK_FAIL_STREAK + 1 ))\n        if (( UNSTUCK_FAIL_STREAK <= UNSTUCK_MAX_EXIT_AI )); then\n          _unstuck_ask non_zero_exit \"$last\" \"$last\" \"$ret\"\n        fi\n      fi\n    fi\n  fi\n\n  _unstuck_queue_pending\n  return $ret\n}\n\n# Hands a pending suggestion to the shell's delivery mechanism.  zsh pre-fills\n# the next buffer by itself (zle-line-init); bash needs an explicit hand-off.\n_unstuck_queue_pending() {\n  [[ -s $UNSTUCK_PENDING ]] || return 0\n  _unstuck_adapter_pending_ready \"$(cat \"$UNSTUCK_PENDING\")\"\n}\n\n# Shell-side facts for `unstuck doctor`.\n_unstuck_doctor() {\n  printf 'shell       : %s\\n' \"$UNSTUCK_NAME\"\n  _unstuck_adapter_doctor\n  printf 'runtime     : %s\\n' \"${UNSTUCK_CMD[*]}\"\n  printf 'session dir : %s %s\\n' \"$UNSTUCK_SESSION_DIR\" \"$([[ -w $UNSTUCK_SESSION_DIR ]] && printf '可写' || printf '不可写')\"\n}\n\n# User-facing entry points (both shells get the same names).\nunstuck-doctor() { _unstuck_doctor; }\nunstuck-reload() { _unstuck_reload; }\n",
  "plugin/zsh/adapter.zsh": "# zsh adapter: hooks, line-editor access, history.\n#\n# Everything here is zsh-specific.  The core calls these; see\n# plugin/lib/unstuck-core.sh for the interface.\n\n_unstuck_adapter_init() {\n  autoload -Uz add-zsh-hook add-zle-hook-widget\n  add-zsh-hook preexec _unstuck_zsh_preexec\n  add-zsh-hook precmd _unstuck_zsh_precmd\n  add-zsh-hook zshexit _unstuck_zsh_exit\n\n  # Scenario 2.  zsh runs this in a subshell (measured), so the suggestion can\n  # only travel to the parent through the pending file.\n  command_not_found_handler() { _unstuck_on_not_found \"$1\"; }\n\n  # Compose: keep whatever already owned accept-line (another plugin's wrapper).\n  if [[ -v widgets[accept-line] && ${widgets[accept-line]} != builtin ]]; then\n    zle -A accept-line _unstuck_outer_accept\n  fi\n  zle -N accept-line _unstuck_zsh_accept_line\n  add-zle-hook-widget line-init _unstuck_zsh_line_init\n}\n\n_unstuck_adapter_finish() {\n  # add-zsh-hook / add-zle-hook-widget ignore duplicates, so a reload is safe.\n  return 0\n}\n\n_unstuck_adapter_history() {\n  local limit=${1:-20}\n  local -a keys=(${(on)${(k)history}}) recent=()\n  # A short array would make ${arr[-limit,-1]} empty in zsh — clamp explicitly.\n  (( ${#keys} > limit )) && keys=(\"${keys[-${limit},-1]}\")\n  local key\n  for key in \"${keys[@]}\"; do recent+=(\"${history[$key]}\"); done\n\n  # A fresh shell's $history is empty (zsh does not preload the history file).\n  if (( ${#recent} < limit )) && [[ -r ${HISTFILE-} ]]; then\n    local line\n    local -a past=()\n    for line in \"${(@f)$(command tail -n \"$limit\" -- \"$HISTFILE\" 2>/dev/null)}\"; do\n      [[ $line == ': '*';'* ]] && line=${line#*;}   # tolerate extended history format\n      [[ -n $line ]] && past+=(\"$line\")\n    done\n    recent=(\"${past[@]}\" \"${recent[@]}\")\n    (( ${#recent} > limit )) && recent=(\"${recent[-${limit},-1]}\")\n  fi\n\n  (( ${#recent} )) && printf '%s\\n' \"${recent[@]}\"\n  return 0\n}\n\n_unstuck_adapter_not_found_message() { printf 'zsh: command not found: %s\\n' \"$1\" >&2; }\n\n_unstuck_adapter_command_exists() { whence -w \"$1\" >/dev/null 2>&1 }\n\n_unstuck_adapter_supports_comment() { [[ -o interactive_comments ]] }\n\n# zsh pre-fills the next buffer itself (zle-line-init), so nothing to arm here.\n_unstuck_adapter_pending_ready() { return 0 }\n\n_unstuck_adapter_delivery() { printf 'prefill'; }\n\n_unstuck_adapter_doctor() {\n  if [[ ${widgets[accept-line]-} == user:_unstuck_zsh_accept_line ]]; then\n    printf 'accept-line : unstuck 已接管\\n'\n  else\n    printf 'accept-line : %s（不是 unstuck，可能被别的插件覆盖）\\n' \"${widgets[accept-line]:-builtin}\"\n  fi\n  printf 'line-init   : %s\\n' \"${widgets[zle-line-init]:-（未注册）}\"\n  printf 'comments    : %s\\n' \"${options[interactive_comments]}\"\n}\n\n# --- hooks -------------------------------------------------------------------\n\n_unstuck_zsh_preexec() { UNSTUCK_LAST_CMD=$1 }\n\n_unstuck_zsh_precmd() {\n  local ret=$?\n  # An empty line keeps $? (measured in both shells), so without this guard a\n  # bare Enter after a failure would re-analyse the same command.\n  local marker=${HISTCMD:-0}\n  if [[ $marker == ${UNSTUCK_LAST_HISTCMD:-} ]]; then\n    _unstuck_on_prompt 0 \"\"\n    return $ret\n  fi\n  typeset -g UNSTUCK_LAST_HISTCMD=$marker\n  _unstuck_on_prompt \"$ret\" \"$UNSTUCK_LAST_CMD\"\n  return $ret\n}\n\n# Scenario 1 — natural language typed at the prompt.\n#\n# Do NOT print the panel here: ZLE's line accounting is stale while a widget\n# runs, and its redraw after the widget erases the tail of whatever we wrote\n# (measured: ESC[A×3 + ESC[J wiped the command line, the footer and the blank\n# line).  Hand the query to precmd, which runs with ZLE inactive.\n_unstuck_zsh_accept_line() {\n  if ! _unstuck_should_intercept_line \"$BUFFER\"; then\n    if [[ -v widgets[_unstuck_outer_accept] ]]; then\n      zle _unstuck_outer_accept\n    else\n      zle .accept-line\n    fi\n    return 0\n  fi\n  typeset -g UNSTUCK_QUERY=$BUFFER\n  BUFFER=\"\" CURSOR=0\n  zle .accept-line\n}\n\n# Delivery: zle-line-init runs inside a widget, so BUFFER can be set here (unlike\n# from the command-not-found subshell).  At line-init the buffer is empty, so\n# nothing the user typed can be clobbered.\n_unstuck_zsh_line_init() {\n  [[ -s $UNSTUCK_PENDING ]] || return 0\n  local suggestion\n  suggestion=$(cat \"$UNSTUCK_PENDING\")\n  [[ -n $suggestion ]] || return 0\n  rm -f -- \"$UNSTUCK_PENDING\"\n  BUFFER=$suggestion CURSOR=${#suggestion}\n}\n\n_unstuck_zsh_exit() {\n  zmodload zsh/system 2>/dev/null\n  [[ ${sysparams[pid]} == $$ ]] || return 0   # subshell: leave the parent's dir alone\n  rm -rf -- \"$UNSTUCK_SESSION_DIR\"\n}\n",
  "plugin/zsh/unstuck.zsh": "# Unstuck — zsh integration entry point (zsh 5.9+).\n#\n# The policy, context assembly and runtime bridge live in\n# plugin/lib/unstuck-core.sh; this directory only implements what is\n# zsh-specific (see plugin/zsh/adapter.zsh).\n\nif [[ -n ${UNSTUCK_LOADED-} ]]; then\n  return 0\nfi\ntypeset -g UNSTUCK_LOADED=1\ntypeset -g UNSTUCK_NAME=zsh\ntypeset -g UNSTUCK_EXT=zsh\n\n# <repo>/plugin/zsh/unstuck.zsh -> <repo>\ntypeset -g UNSTUCK_ROOT=${${(%):-%x}:A:h:h:h}\n\n# $EPOCHREALTIME feeds the latency column of the log.\nzmodload zsh/datetime 2>/dev/null\n\n. \"$UNSTUCK_ROOT/plugin/lib/unstuck-core.sh\"\n. \"$UNSTUCK_ROOT/plugin/zsh/adapter.zsh\"\n\n_unstuck_setup\n",
};
